function percentOff(amount: number, percent: number): number {
  return Math.round(amount * (1 - percent / 100));
}

function applyCouponCode(amount: number, code: string): number {
  if (code === "SAVE10") return percentOff(amount, 10);
  if (code === "SAVE20") return percentOff(amount, 20);
  return amount;
}

function isCouponExpired(issuedAt: Date, validDays: number): boolean {
  const ageMs = Date.now() - issuedAt.getTime();
  return ageMs > validDays * 24 * 60 * 60 * 1000;
}

function bestDiscount(amount: number, codes: string[]): number {
  return codes.reduce((best, code) => Math.min(best, applyCouponCode(amount, code)), amount);
}
